<script setup>
import { onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { api, time, codeStates, stateType } from '../../api'
import { usePage } from '../../composables/usePage'
import { ElMessage, ElMessageBox } from 'element-plus'
import LoadState from '../../components/LoadState.vue'
const route = useRoute(), filters = reactive({ productId: route.query.productId ? Number(route.query.productId) : '', status: '' }), { rows, total, page, loading, error, load, search } = usePage('/admin/redeem-codes', filters)
const products = ref([]), productsError = ref(''), dialog = ref(false), saving = ref(false), formError = ref(''), result = ref(null), fileInput = ref(null), disabling = ref(null)
const form = reactive({ productId: filters.productId || '', codes: '', expiredAt: '' })
async function loadProducts() { productsError.value = ''; try { const all = []; let productPage = 1; while (true) { const data = await api.get('/admin/products', { params: { page: productPage++, size: 100 } }); all.push(...data.records); if (all.length >= data.total || !data.records.length) break }; products.value = all } catch (e) { productsError.value = e.message } }
function open() { form.productId = filters.productId || ''; form.codes = ''; form.expiredAt = ''; formError.value = ''; result.value = null; dialog.value = true; if (!products.value.length) loadProducts() }
async function importCodes() { formError.value = ''; result.value = null; if (!form.productId || !form.codes.trim()) { formError.value = '请选择商品并输入兑换码。'; return }; saving.value = true; try { result.value = await api.post('/admin/redeem-codes/import', { productId: form.productId, codes: form.codes, expiredAt: form.expiredAt || null }); ElMessage.success('导入处理完成'); form.codes = ''; await load() } catch (e) { formError.value = e.message } finally { saving.value = false } }
async function fileChanged(event) { const file = event.target.files?.[0]; if (!file) return; if (file.size > 1024 * 1024) { ElMessage.error('文件最大为 1 MB。'); event.target.value = ''; return }; try { const text = (await file.text()).replace(/^\uFEFF/, ''); const lines = text.split(/\r?\n/).map(line => { const match = line.match(/^\s*"((?:[^"]|"")*)"(?:,|$)/); return match ? match[1].replace(/""/g, '"') : line.split(',')[0].trim() }).filter(Boolean); if (/^(code|兑换码|卡密)$/i.test(lines[0] || '')) lines.shift(); form.codes = lines.join('\n'); ElMessage.success(`已读取 ${lines.length} 行，确认后导入。`) } catch { ElMessage.error('无法读取文件。') }; event.target.value = '' }
async function disable(row) { try { const answer = await ElMessageBox.prompt('请输入作废原因。此操作会记录审计日志。', '作废未使用兑换码', { confirmButtonText: '确认作废', cancelButtonText: '取消', inputPlaceholder: '例如：导入错误', inputValidator: value => !!value?.trim() && value.length <= 200 || '请填写 1～200 字的原因', type: 'warning' }); disabling.value = row.id; await api.post(`/admin/redeem-codes/${row.id}/disable`, { reason: answer.value.trim() }); ElMessage.success('兑换码已作废'); await load() } catch (e) { if (e instanceof Error) ElMessage.error(e.message) } finally { disabling.value = null } }
onMounted(() => { load(); loadProducts() })
</script>
<template><div class="page-heading"><div><div class="eyebrow">REDEEM CODE INVENTORY</div><h1>卡密库存</h1><p>批量导入兑换码，跟踪分配与使用状态。</p></div><el-button type="primary" @click="open">＋ 批量导入</el-button></div><el-alert v-if="productsError" :title="`商品选项加载失败：${productsError}`" type="error" :closable="false" class="form-alert" /><section class="surface admin-table-panel"><form class="table-toolbar" @submit.prevent="search"><el-select v-model="filters.productId" placeholder="全部商品" clearable filterable aria-label="所属商品" @change="search"><el-option v-for="product in products" :key="product.id" :label="product.name" :value="product.id" /></el-select><el-select v-model="filters.status" placeholder="全部状态" clearable aria-label="兑换码状态" @change="search"><el-option v-for="(label, state) in codeStates" :key="state" :label="label" :value="state" /></el-select><el-button native-type="submit">查询</el-button><span class="toolbar-count">共 {{ total }} 条 · 默认脱敏</span></form><LoadState :loading="loading" :error="error" :empty="!rows.length" empty-text="暂无符合条件的兑换码" @retry="load"><el-table :data="rows"><el-table-column prop="id" label="ID" width="70" /><el-table-column prop="code" label="兑换码（脱敏）" min-width="160"><template #default="{ row }"><span class="mono">{{ row.code }}</span></template></el-table-column><el-table-column prop="productName" label="所属商品" min-width="140" /><el-table-column label="状态" width="110"><template #default="{ row }"><el-tag :type="stateType(row.status)">{{ codeStates[row.status] || row.status }}</el-tag></template></el-table-column><el-table-column prop="orderNo" label="绑定订单" min-width="210" /><el-table-column label="有效期至" min-width="170"><template #default="{ row }">{{ row.expiredAt ? time(row.expiredAt) : '长期有效' }}</template></el-table-column><el-table-column label="导入 / 使用时间" min-width="190"><template #default="{ row }"><span>{{ time(row.createdAt) }}</span><p v-if="row.usedAt" class="table-subtitle">使用：{{ time(row.usedAt) }}</p></template></el-table-column><el-table-column label="操作" width="90" fixed="right"><template #default="{ row }"><el-button v-if="['UNUSED', 'ASSIGNED'].includes(row.status)" link type="danger" :loading="disabling === row.id" @click="disable(row)">作废</el-button><span v-else class="muted">—</span></template></el-table-column></el-table><el-pagination v-if="total > 15" v-model:current-page="page" :page-size="15" :total="total" layout="total, prev, pager, next" class="pagination" @current-change="load" /></LoadState></section><el-dialog v-model="dialog" title="批量导入兑换码" width="620px" :close-on-click-modal="!saving"><el-alert v-if="formError" :title="formError" type="error" :closable="false" show-icon class="form-alert" /><div v-if="result" class="import-result"><div><strong>{{ result.successCount }}</strong><span>成功导入</span></div><div><strong>{{ result.duplicateCount }}</strong><span>重复跳过</span></div><div><strong>{{ result.invalidCount }}</strong><span>格式错误</span></div></div><el-form label-position="top" @submit.prevent="importCodes"><el-form-item label="所属商品（必填）"><el-select v-model="form.productId" filterable placeholder="请选择商品" class="full-width"><el-option v-for="product in products" :key="product.id" :label="product.name" :value="product.id" /></el-select><el-button v-if="productsError" link type="primary" @click="loadProducts">重试加载商品</el-button></el-form-item><el-form-item label="有效期至（可选，留空长期有效）"><el-date-picker v-model="form.expiredAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="选择失效时间" class="full-width" /></el-form-item><div class="panel-title"><label class="field-label">兑换码（每行一个）</label><el-button size="small" @click="fileInput?.click()">读取 TXT / CSV</el-button><input ref="fileInput" type="file" accept=".txt,.csv" class="hidden" @change="fileChanged" /></div><el-input v-model="form.codes" type="textarea" :rows="8" :maxlength="1000000" placeholder="CODE-EXAMPLE-001&#10;CODE-EXAMPLE-002" class="mono-input" /><p class="form-help">每条 4～128 位英文字母、数字、下划线或连字符，每次最多 10000 行。自动去除空格和空行并跳过重复；CSV 读取第一列，最大 1 MB。</p></el-form><template #footer><el-button :disabled="saving" @click="dialog = false">关闭</el-button><el-button type="primary" :loading="saving" @click="importCodes">确认导入</el-button></template></el-dialog></template>
